window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING['lesson-12']={
version:1,title:'Vegetarian Diets for Adolescents',chapter:'Chapter 14 + current adolescent guidance',duration:'80–95 minutes',
outcomes:['Relate pubertal growth, activity and menstruation to changing energy and nutrient needs.','Plan practical vegetarian protein, iron, zinc, calcium, vitamin D and B12 strategies for adolescents.','Use evidence-aware language about soy, fibre and health outcomes.','Distinguish vegetarian identity from eating-disorder risk while screening restriction respectfully.','Build collaborative plans that fit school, sport, culture, budget and increasing autonomy.'],
modules:[
{id:'growth',title:'Fuel growth and autonomy',summary:'Connect rapid development with enough food, practical access and adolescent choice.',moments:[
{id:'l12-m1',title:'Adolescence changes needs and decision-making at once',highYield:'Puberty increases demands while adolescents gain control over food choices, schedules and identity.',teaching:['Adolescent growth includes changes in height, lean tissue, fat tissue, blood volume and bone. Timing differs markedly between individuals, so chronological age alone cannot define energy need. Activity, menstrual status, health, growth history and developmental stage all contribute.','Food decisions increasingly happen at school, work, sport and with peers. A nutritionally sound plan that ignores convenience, cost, taste, culture or autonomy will not be used. Collaborative counselling asks what vegetarianism means to the teen and what foods are realistically available.'],keyPoints:['Puberty timing varies.','Energy need is individual.','Autonomy affects implementation.','Context belongs in assessment.'],visual:{title:'Adolescent nutrition context',kind:'map',items:[{label:'Growth',detail:'Height, lean tissue, blood and bone'},{label:'Activity',detail:'Sport, transport, work and recovery'},{label:'Body changes',detail:'Menstruation and changing composition'},{label:'Autonomy',detail:'Identity, peers, schedule, money and food access'}]},mnemonic:{title:'G-A-B-A',cue:'Growth · Activity · Body changes · Autonomy',explanation:'Four drivers of an adolescent plan.'},goodToKnow:'Adolescence is not the fastest growth period of life—infancy is faster—but puberty is a major later growth spurt.',practiceConnection:'Ask the adolescent directly and protect appropriate privacy while involving caregivers according to age, safety and local practice.',activity:{prompt:'Which approach best estimates an adolescent’s nutrition needs?',options:[{text:'Consider growth stage, activity, menstrual status, health and usual intake',correct:true,feedback:'Correct. Needs are not determined by age alone.'},{text:'Use the same meal plan for every teenager',correct:false,feedback:'Growth timing and activity vary widely.'},{text:'Judge adequacy from body size alone',correct:false,feedback:'Size cannot reveal intake quality, function or deficiency.'}]}},
{id:'l12-m2',title:'Energy and protein support both growth and recovery',highYield:'Vegetarian adolescents need sufficient total energy and varied protein; active teens may need more total protein, not a special protein percentage rule.',teaching:['Legumes, tofu, tempeh, soy foods, seitan when appropriate, nuts, seeds, grains, and included eggs or dairy can build a varied protein pattern. Plant-protein digestibility and amino-acid distribution differ, so adequate total energy, quantity and variety matter.','Sports increase total energy and may increase protein need, but saying all active teens require a higher percentage of calories from protein can mislead: energy need can rise at the same time. Meal timing, carbohydrate availability, hydration and recovery foods are part of performance nutrition.'],keyPoints:['Energy adequacy supports growth.','Protein comes from varied foods.','Activity can raise total protein need.','Percentage of energy is not the whole story.'],visual:{title:'Training-day foundation',kind:'layers',items:[{label:'Enough energy',detail:'Regular meals and snacks'},{label:'Carbohydrate',detail:'Training fuel and glycogen restoration'},{label:'Protein',detail:'Distributed recovery and growth'},{label:'Fluids + micronutrients',detail:'Hydration and nutrient-dense choices'}]},mnemonic:{title:'E-C-P-F',cue:'Energy · Carbohydrate · Protein · Fluids',explanation:'A performance pattern is more than a protein target.'},goodToKnow:'Current adult sports evidence does not show inherent performance harm from a well-planned plant-based pattern, but long-term elite adolescent evidence is limited.',practiceConnection:'Refer young athletes with weight change, menstrual disruption, injury, fatigue, restrictive eating or performance decline for sports and medical assessment.',activity:{prompt:'What is the best protein message for an active vegetarian teen?',options:[{text:'Meet higher total needs with varied foods while protecting total energy and carbohydrate',correct:true,feedback:'Correct. Performance nutrition is an integrated pattern.'},{text:'Remove carbohydrate and replace it entirely with protein',correct:false,feedback:'Carbohydrate is important training fuel.'},{text:'Protein percentage must always double',correct:false,feedback:'Needs should be individualized in grams and context.'}]}}
]},
{id:'nutrients',title:'Prioritize bone, blood and reliable fortification',summary:'Use food patterns, labels and symptoms to find likely nutrient gaps.',moments:[
{id:'l12-m3',title:'Bone building needs calcium, vitamin D, energy and loading',highYield:'Adolescence is a major bone-accrual window; calcium alone cannot compensate for low energy, low vitamin D or absent weight-bearing activity.',teaching:['Bone mineral accrual accelerates during puberty. Calcium-rich foods may include fortified beverages and yogurts, calcium-set tofu, appropriate dairy where included, and low-oxalate greens. Labels matter because plant-product fortification varies.','Vitamin D supports calcium regulation and is difficult to obtain from unfortified foods. Local supplement guidance, sun exposure, skin pigmentation, season and health conditions influence planning. Weight-bearing activity and adequate energy/protein also support bone.'],keyPoints:['Puberty is a major bone-building period.','Verify calcium fortification.','Vitamin D usually needs explicit planning.','Energy and loading matter to bone.'],visual:{title:'Four-part bone plan',kind:'map',items:[{label:'Calcium',detail:'Foods and verified fortification'},{label:'Vitamin D',detail:'Local guidance, fortified foods and/or supplement'},{label:'Energy + protein',detail:'Substrate for growth'},{label:'Loading',detail:'Weight-bearing and resistance activity'}]},mnemonic:{title:'C-D-E-L',cue:'Calcium · D · Energy · Loading',explanation:'Four pillars of adolescent bone support.'},goodToKnow:'Almond butter contributes nutrients but is not a nutritional replacement for milk; compare the whole product profile.',practiceConnection:'Bone pain, repeated stress injury, menstrual disruption or significant restriction warrants clinical evaluation, not only a calcium handout.',activity:{prompt:'Which plan best supports adolescent bone health?',options:[{text:'Adequate energy and protein, calcium, vitamin D and weight-bearing activity',correct:true,feedback:'Correct. Bone health is multi-factorial.'},{text:'Calcium alone while energy intake remains low',correct:false,feedback:'Low energy availability can undermine bone health.'},{text:'Avoid all activity to preserve calcium',correct:false,feedback:'Appropriate loading supports bone adaptation.'}]}},
{id:'l12-m4',title:'Iron, zinc and B12 require different strategies',highYield:'Iron absorption, zinc bioavailability and B12 reliability are separate problems; one supplement rule cannot solve all three.',teaching:['Menstruation, growth and endurance activity can raise concern about iron status. Plant foods provide nonheme iron, whose absorption improves with vitamin C and falls with some phytate/polyphenol contexts. Symptoms and risk may justify ferritin and clinical assessment; routine high-dose iron is not benign.','Zinc is present in legumes, nuts, seeds, whole grains, tempeh and other foods; soaking, sprouting, fermenting and leavening can improve bioavailability. Vitamin B12 must come from a dependable fortified food or supplement in vegan patterns. Dairy can contribute zinc in lacto-ovo patterns but should not crowd out iron-rich foods.'],keyPoints:['Pair iron with vitamin C.','Assess before high-dose iron.','Use preparation methods for zinc.','Make B12 reliability explicit.'],visual:{title:'Three nutrient strategies',kind:'comparison',items:[{label:'Iron',detail:'Food sources + vitamin C + assess status when indicated'},{label:'Zinc',detail:'Variety + preparation methods + adequacy'},{label:'B12',detail:'Verified fortification or supplement'}]},mnemonic:{title:'I-Z-B',cue:'Iron interaction · Zinc preparation · B12 reliability',explanation:'Each nutrient has a different planning lever.'},goodToKnow:'The older claim that vegetarians universally need “50% more zinc” is too blunt; intake, phytate and individual context matter.',practiceConnection:'Fatigue can reflect many causes. Do not diagnose iron or B12 deficiency from fatigue alone, but do not dismiss it when risk factors are present.',activity:{prompt:'Which meal change directly improves nonheme iron absorption?',options:[{text:'Add a vitamin-C-rich food to an iron-rich meal',correct:true,feedback:'Correct. Vitamin C promotes nonheme iron absorption.'},{text:'Take high-dose zinc with every meal',correct:false,feedback:'This does not target iron absorption and may create imbalance.'},{text:'Rely on unfortified seaweed for B12',correct:false,feedback:'Seaweed is not a reliable B12 source.'}]}}
]},
{id:'identity',title:'Counsel without myths or stigma',summary:'Separate evidence, identity and eating-disorder risk with careful questions.',moments:[
{id:'l12-m5',title:'Vegetarian identity is not an eating-disorder diagnosis',highYield:'Most vegetarian adolescents do not have an eating disorder, but dietary labels can sometimes conceal or legitimize escalating restriction.',teaching:['Do not assume that becoming vegetarian causes an eating disorder. Ask when and why the pattern changed, which foods were removed, whether acceptable alternatives replaced them, and how the teen feels about eating, weight and body shape.','Warning signs include rapid expansion of rules, fear-driven avoidance, skipped meals, secretive behavior, weight or growth change, menstrual disruption, compulsive exercise, dizziness, injury, distress and social withdrawal. Screening must be nonjudgmental and followed by appropriate referral.'],keyPoints:['Vegetarianism is not a diagnosis.','Ask about timing and motivation.','Look for function and growth changes.','Refer when warning signs are present.'],visual:{title:'Identity-to-risk continuum',kind:'sequence',items:[{label:'Value or preference',detail:'Ethics, environment, religion, taste or family pattern'},{label:'Planned substitution',detail:'Removed foods replaced with adequate alternatives'},{label:'Escalating rules',detail:'More exclusions, anxiety and rigidity'},{label:'Functional harm',detail:'Growth, menstrual, medical, social or psychological change'}]},mnemonic:{title:'W-R-F',cue:'Why · Replacements · Function',explanation:'Three respectful questions before interpreting restriction.'},goodToKnow:'A sudden vegetarian label can be a useful opening for conversation without being treated as proof of pathology.',practiceConnection:'Use validated screening and coordinate with adolescent medicine and eating-disorder specialists when concern is present; avoid praise for weight loss.',activity:{prompt:'What is the most appropriate response to a teen who recently became vegetarian?',options:[{text:'Explore motivation, substitutions, rules, growth and function without assuming a disorder',correct:true,feedback:'Correct. Curiosity and safety can coexist.'},{text:'Diagnose an eating disorder immediately',correct:false,feedback:'Vegetarian identity alone is not diagnostic.'},{text:'Ignore rapid weight loss because vegetarian diets are healthy',correct:false,feedback:'Functional red flags require assessment regardless of diet label.'}]}},
{id:'l12-m6',title:'Soy myths should not drive adolescent advice',highYield:'Soy foods can contribute high-quality protein; current evidence does not support teaching that ordinary soy intake raises later breast-cancer risk.',teaching:['Tofu, tempeh, edamame and fortified soy foods can provide protein and other nutrients. Isoflavones are not equivalent to human estrogen, and observational research has not established that eating soy in childhood or adolescence increases breast-cancer risk.','Avoid turning association into a guarantee of protection or harm. Food form, overall pattern and individual allergy or medical context matter. Whole and minimally processed soy foods can fit alongside many other protein sources.'],keyPoints:['Soy provides useful protein.','Isoflavones are not human estrogen.','Do not claim ordinary soy raises breast-cancer risk.','Avoid both fear and cure language.'],visual:{title:'Soy evidence filter',kind:'comparison',items:[{label:'Supported',detail:'Soy can be a nutritious protein food'},{label:'Not supported',detail:'Ordinary intake inherently feminizes or causes breast cancer'},{label:'Too strong',detail:'Soy guarantees disease prevention'},{label:'Individualize',detail:'Allergy, preference, access and medical context'}]},mnemonic:{title:'F-E-C',cue:'Food · Evidence · Context',explanation:'Judge soy claims through all three lenses.'},goodToKnow:'Tempeh is fermented soy; tofu is coagulated soy milk. Fermentation changes the food but does not make all nutrient questions disappear.',practiceConnection:'Correct misinformation with concise mechanisms and sources rather than debating ideology.',activity:{prompt:'Which soy statement is best supported?',options:[{text:'Soy foods can be one useful protein option in a varied adolescent diet',correct:true,feedback:'Correct. This is evidence-aware and not absolute.'},{text:'Soy inevitably causes breast cancer later in life',correct:false,feedback:'Current evidence does not support this claim.'},{text:'Every adolescent must eat soy daily',correct:false,feedback:'Soy is optional; adequacy can be built in different ways.'}]}}
]},
{id:'implementation',title:'Make the plan work outside the clinic',summary:'Translate evidence into school, sport, social and family routines.',moments:[
{id:'l12-m7',title:'Portable food protects consistency',highYield:'A plan succeeds when nutritious food is available at the time and place the adolescent needs it.',teaching:['School schedules, extracurriculars and part-time work can create long gaps. Portable combinations may include sandwiches with hummus or tofu, bean or lentil bowls, fortified soy beverages, soy yogurt, trail mix where allergy-safe, fruit plus a protein food, or leftovers in safe containers.','Adolescents should help choose options, read labels and plan purchases. Teach a flexible meal structure rather than a perfect menu. Food safety—cold storage, reheating and allergy rules—belongs in the plan.'],keyPoints:['Map the schedule.','Pair carbohydrate with protein and energy.','Let the teen choose acceptable options.','Include food safety.'],visual:{title:'Portable meal formula',kind:'layers',items:[{label:'Base',detail:'Bread, wrap, rice, oats or other grain/starch'},{label:'Protein',detail:'Beans, tofu, tempeh, soy, egg or dairy as applicable'},{label:'Produce',detail:'Fruit or vegetable'},{label:'Energy/flavour',detail:'Seeds, safe nut butter, avocado, oil or sauce'}]},mnemonic:{title:'B-P-P-E',cue:'Base · Protein · Produce · Energy',explanation:'A practical packing formula.'},goodToKnow:'Higher fibre intake can be beneficial, but very high fibre plus low energy can worsen fullness when needs are high.',practiceConnection:'Ask the teen to design two “backup meals” available from their actual school, store or kitchen.',activity:{prompt:'Which lunch best supports a busy vegetarian teen?',options:[{text:'A bean-and-grain wrap with vegetables, sauce and a fortified beverage',correct:true,feedback:'Correct. It combines fuel, protein and micronutrient planning.'},{text:'Only a diet drink',correct:false,feedback:'It does not meet growth or recovery needs.'},{text:'Only raw celery after training',correct:false,feedback:'It lacks adequate energy and protein.'}]}},
{id:'l12-m8',title:'Follow-up measures growth, function and feasibility',highYield:'A good plan is judged by growth and function as well as nutrient calculations.',teaching:['Follow-up can assess growth trajectory, energy, concentration, training recovery, menstrual status where relevant, GI tolerance, supplement reliability, food access and the teen’s experience. Clinician-directed labs may be needed when risk or symptoms justify them.','Review the plan collaboratively: what worked, what was unavailable, what felt socially difficult and what became rigid. This makes counselling supportive rather than policing.'],keyPoints:['Monitor function and growth.','Check supplement reliability.','Use labs when clinically indicated.','Revise collaboratively.'],visual:{title:'Adolescent follow-up dashboard',kind:'map',items:[{label:'Growth',detail:'Trajectory and pubertal context'},{label:'Function',detail:'Energy, focus, recovery and symptoms'},{label:'Pattern',detail:'Meals, variety, fortification and supplements'},{label:'Feasibility',detail:'Cost, access, peers, culture and autonomy'}]},mnemonic:{title:'G-F-P-F',cue:'Growth · Function · Pattern · Feasibility',explanation:'Four outcomes for follow-up.'},goodToKnow:'A diet can look nutritionally complete on paper yet fail if the teen cannot access or tolerate the foods.',practiceConnection:'Agree on one or two teen-selected changes and a follow-up time rather than handing over a long rule list.',activity:{prompt:'Which follow-up question best tests feasibility?',options:[{text:'Which planned foods were actually available at school and practice?',correct:true,feedback:'Correct. Availability determines implementation.'},{text:'Did you follow every rule perfectly?',correct:false,feedback:'Perfection language can increase shame and misses barriers.'},{text:'Can we ignore menstrual and injury changes?',correct:false,feedback:'These can be clinically relevant.'}]}}
]}
],
caseStudy:{title:'A new vegetarian identity and falling performance',scenario:'A 16-year-old runner became vegan three months ago. Meals are often skipped at school, training volume increased, fatigue is worsening and menstruation has become irregular. The teen says the diet is for animals but also expresses intense fear of gaining weight.',prompts:['Which nutrition and medical red flags are present?','How can the clinician respect vegetarian values while addressing possible low energy availability and eating-disorder risk?','Which immediate food, B12, iron and bone-health questions matter?','Who should be involved in coordinated care?'],takeaway:'Support the teen’s values without allowing a diet label to hide low energy availability, nutrient risk or eating-disorder warning signs.'},
recap:['Adolescent needs vary with pubertal stage, activity and health.','Adequate energy and varied protein support growth and training.','Bone health integrates calcium, vitamin D, energy, protein and loading.','Iron, zinc and B12 require different planning strategies.','Vegetarian identity is not an eating-disorder diagnosis.','Sudden escalating restriction and functional change require screening.','Soy foods can fit without fear-based hormone or cancer myths.','Plans must work at school, sport and home and be monitored collaboratively.'],
flashcards:[{front:'Adolescent growth context',back:'Pubertal stage, activity, menstrual status, health and usual intake—not age alone.',tag:'growth'},{front:'Low energy availability',back:'Insufficient dietary energy relative to growth and activity, potentially affecting multiple body systems.',tag:'energy'},{front:'Bone-health quartet',back:'Calcium, vitamin D, adequate energy/protein and weight-bearing activity.',tag:'bone'},{front:'Nonheme iron strategy',back:'Iron-rich foods plus vitamin C; assess status when risk or symptoms justify it.',tag:'iron'},{front:'Zinc strategy',back:'Varied sources and preparation methods that reduce phytate effects.',tag:'zinc'},{front:'B12 strategy',back:'Dependable fortified food and/or supplement plan.',tag:'B12'},{front:'Vegetarian identity',back:'A food-pattern identity, not an eating-disorder diagnosis.',tag:'counselling'},{front:'Restriction screen',back:'Why the change, what replacements exist, and what growth/function changes followed.',tag:'counselling'},{front:'Soy isoflavones',back:'Plant compounds that are not equivalent to human estrogen.',tag:'soy'},{front:'Performance pattern',back:'Enough energy, carbohydrate, protein, fluids and micronutrients.',tag:'sport'},{front:'Portable meal formula',back:'Base, protein, produce and energy/flavour.',tag:'practice'},{front:'Follow-up dashboard',back:'Growth, function, pattern and feasibility.',tag:'practice'}],
practice:[{prompt:'Name four drivers of adolescent needs.',answer:'Growth stage, activity, body changes/menstruation and autonomy/context.',rationale:'Needs and implementation change together.',tag:'growth'},{prompt:'Why is a protein percentage rule incomplete?',answer:'Total energy also changes; grams, distribution and overall fuel matter.',rationale:'Percent can stay stable while absolute need rises.',tag:'protein'},{prompt:'State the four-part bone plan.',answer:'Calcium, vitamin D, energy/protein and weight-bearing activity.',rationale:'Bone is multi-factorial.',tag:'bone'},{prompt:'Improve an iron-rich meal in one step.',answer:'Add a vitamin-C-rich food.',rationale:'Vitamin C enhances nonheme iron absorption.',tag:'iron'},{prompt:'What makes B12 reliable?',answer:'A verified dose/frequency from fortified foods or supplements.',rationale:'Plant-food assumptions are unsafe.',tag:'B12'},{prompt:'How should soy-cancer claims be framed?',answer:'Ordinary soy foods are not shown to increase breast-cancer risk; avoid both fear and cure claims.',rationale:'Current evidence does not support the old warning.',tag:'soy'},{prompt:'Name three eating-disorder warning signs.',answer:'Rapid restriction, weight/growth change, menstrual disruption, compulsive exercise, dizziness, injury, distress or social withdrawal.',rationale:'Functional change matters.',tag:'counselling'},{prompt:'Build a portable meal with BPPE.',answer:'Choose a base, protein, produce and energy/flavour component.',rationale:'The formula supports practicality.',tag:'practice'},{prompt:'What should sports follow-up include?',answer:'Energy, recovery, injury, menstrual status, growth, hydration and food access.',rationale:'Performance reflects the whole pattern.',tag:'sport'},{prompt:'Why ask about feasibility?',answer:'A nutritionally complete plan fails if foods are unaffordable, unavailable or socially unacceptable.',rationale:'Implementation is an outcome.',tag:'practice'}]
};

// Evidence-strengthening extension: adolescent energy availability, supplement safety and shared decision-making.
window.VN_LEARNING['lesson-12'].version=2;
window.VN_LEARNING['lesson-12'].sources=[{title:'Canadian Paediatric Society · Vegetarian diets for children and teens (reviewed 2024)',url:'https://caringforkids.cps.ca/handouts/preteens-and-teens/vegetarian_diets_for_children_and_teens'},{title:'IOC consensus statement · Relative Energy Deficiency in Sport (2023)',url:'https://doi.org/10.1136/bjsports-2023-106994'},{title:'FDA · Examining dietary supplements for teen learners',url:'https://www.fda.gov/food/students-teachers/science-and-our-food-supply'},{title:'American Cancer Society · Soy foods and cancer risk',url:'https://www.cancer.org/cancer/risk-prevention/diet-physical-activity/how-diet-and-physical-activity-impact-cancer-risk.html'},{title:'NIH ODS · Iron fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/Iron-HealthProfessional/'},{title:'NIH ODS · Vitamin B12 fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/'}];
window.VN_LEARNING['lesson-12'].duration='105–120 minutes';
window.VN_LEARNING['lesson-12'].outcomes.push('Recognize the multi-system pattern of low energy availability and refer without blaming vegetarian identity.','Evaluate supplements, social-media claims and school or sport barriers with an autonomy-supportive process.');
window.VN_LEARNING['lesson-12'].modules.push({id:'adolescent-reasoning',title:'Apply adolescent-specific clinical reasoning',summary:'Connect growth, sport, menstruation, supplement use and autonomy instead of treating them as separate topics.',moments:[
{id:'l12-m9',title:'Low energy availability is a whole-body problem',highYield:'When intake does not cover growth, daily life and training, the effects can extend far beyond weight or athletic performance.',teaching:['Energy availability describes the energy left for normal physiology after exercise demands are considered. A teen can experience low availability intentionally or unintentionally: missed school meals, high training load, food insecurity, GI symptoms, poor planning after removing animal foods, body-image pressure or an eating disorder can all contribute. Vegetarian identity is not the cause, but an inadequately replaced restriction can widen the gap.','Potential signals include falling performance, persistent fatigue, recurrent injuries, impaired recovery, mood or concentration change, feeling cold, menstrual disruption where applicable, delayed growth or puberty, and stress fractures. Body size alone cannot rule the problem in or out. These signals require qualified assessment because other medical conditions can look similar.','The first nutrition question is whether eating opportunities match the teen day. Map breakfast, school access, pre-activity fuel, recovery food, evening meals and weekends. Carbohydrate supports high-intensity work and recovery; protein, total energy, iron, calcium, vitamin D, B12 and sleep also matter. The goal is not to earn food through exercise but to fuel growth and function consistently.'],keyPoints:['Low energy availability can be unintentional.','Normal body size does not exclude risk.','Review the full school-and-sport day.','Menstrual, bone, growth and performance changes require assessment.'],visual:{title:'Energy-availability systems map',kind:'map',items:[{label:'Input',detail:'Meals, snacks, fluids and recovery food'},{label:'Demand',detail:'Growth, school, training and daily activity'},{label:'Signals',detail:'Fatigue, injury, recovery, mood, concentration and menstrual change'},{label:'Response',detail:'Clinical assessment plus a feasible fuelling plan'}]},mnemonic:{title:'G-S-T-R',cue:'Growth · School · Training · Recovery',explanation:'Map all four demands before judging whether intake is sufficient.'},goodToKnow:'The current sport-medicine framework describes low energy availability as affecting multiple systems and people of any sex; it is not limited to the older female athlete triad concept.',practiceConnection:'Ask permission to discuss periods, body image, food access and supplement use privately and respectfully; involve caregivers according to age, safety and local practice.',activity:{prompt:'Which finding best rules out low energy availability?',options:[{text:'None of these alone—body size, diet label and performance must be interpreted with symptoms and the full intake-demand pattern',correct:true,feedback:'Correct. No single visible feature excludes it.'},{text:'A body weight in the expected range',correct:false,feedback:'Low energy availability can occur across body sizes.'},{text:'Identifying as vegetarian',correct:false,feedback:'Vegetarian identity neither diagnoses nor excludes the condition.'}]}},
{id:'l12-m10',title:'Supplements and social media require a claim-by-claim filter',highYield:'A supplement is useful only when it has a clear job, an appropriate dose and a safe product—not because it is popular or labelled natural.',teaching:['Start by naming the job: correct a diagnosed deficiency, provide reliable B12, fill a documented intake gap, support a clinician-directed treatment, or add convenience. Then check dose, age suitability, interactions, allergens and third-party quality certification where relevant. More is not necessarily better: excess iron is harmful, preformed vitamin A can be toxic, and products marketed for muscle or weight loss may contain undeclared or unsafe ingredients.','Protein powders are not automatically required for vegetarian athletes. First assess total energy, regular meals and ordinary protein foods such as soy, legumes, dairy or eggs if used, seitan, nuts and seeds. A powder may be a convenient food-like tool in some schedules, but it cannot repair chronic under-fuelling, inadequate B12 or a disordered eating pattern.','Use a three-source test for online claims: Is the claim tied to a specific outcome? Does it come from an independent, reputable source rather than a seller? Does the evidence apply to adolescents, the dose used and the actual product? Teach the teen to compare claims without humiliating them; curiosity builds better judgment than a lecture.'],keyPoints:['Define the supplement job first.','Check dose, age, interactions and product quality.','Food-first does not mean supplement-never.','Evaluate the claim, source and applicability separately.'],visual:{title:'Supplement decision gate',kind:'sequence',items:[{label:'Job',detail:'What specific gap or clinical goal is it meant to address?'},{label:'Need',detail:'What intake, symptom or clinical evidence supports use?'},{label:'Safety',detail:'Dose, age, interactions, allergens and quality'},{label:'Fit',detail:'Can the teen obtain and use it consistently?'},{label:'Follow-up',detail:'How will benefit or harm be assessed?'}]},mnemonic:{title:'J-N-S-F-F',cue:'Job · Need · Safety · Fit · Follow-up',explanation:'Five gates before recommending or dismissing a supplement.'},goodToKnow:'Natural, vegan and athlete-friendly are marketing descriptions, not proof of dose accuracy, purity or effectiveness.',practiceConnection:'Invite the teen to show the exact product or post. Review it together and agree on one decision, one reason and one follow-up rather than issuing a blanket ban.',activity:{prompt:'A vegetarian teen athlete asks whether a protein powder is necessary. What is the best first response?',options:[{text:'Assess total energy, usual protein foods, schedule and the specific product before deciding',correct:true,feedback:'Correct. Need and safety depend on the whole pattern.'},{text:'All vegetarian athletes need protein powder',correct:false,feedback:'Many can meet needs with ordinary foods.'},{text:'All supplements are useless and should be dismissed immediately',correct:false,feedback:'Some supplements, including reliable B12, can have a clear role.'}]}}
]});
window.VN_LEARNING['lesson-12'].flashcards.push({front:'Low energy availability',back:'Energy remaining for normal physiology is insufficient after activity demands; effects can involve many body systems.',tag:'energy'},{front:'Teen fuelling map',back:'Review growth, school, training and recovery across the actual day.',tag:'energy'},{front:'Supplement decision gate',back:'Job, need, safety, fit and follow-up.',tag:'supplements'});
window.VN_LEARNING['lesson-12'].practice.push({prompt:'Name four non-weight signals that may accompany low energy availability.',answer:'Examples include fatigue, declining performance, poor recovery, recurrent injury, stress fracture, menstrual change, mood or concentration change, feeling cold, or altered growth.',rationale:'The problem is multi-system and cannot be screened by appearance alone.',tag:'energy'},{prompt:'What should be established before recommending a supplement?',answer:'Its specific job, evidence of need, safe age-appropriate dose and product, practical fit, and follow-up plan.',rationale:'A supplement decision is a clinical reasoning process, not a label reaction.',tag:'supplements'});
